export function hierarchicalTaskOrchestration(tasks, prioritySignals) {
  const sortedTasks = tasks.sort((a, b) => prioritySignals[b] - prioritySignals[a]);
  const results = [];
  for (const task of sortedTasks) {
    if (task.canExecute()) {
      results.push(task.execute());
    } else {
      task.escalate();
    }
  }
  return results;
}